changeSet.sql:
INSERT INTO public.identity_provider (type, server_url)
VALUES ('GITHUB', 'https://github.com'), ('GITLAB', 'https://gitlab.com'), ('SLACK', 'https://slack.com');
INSERT INTO public.instance_settings (id, silent_mode_engaged) VALUES (1, TRUE);
INSERT INTO public.instance_llm_settings (id, allowed_egress_hosts, allow_workspace_connections)
VALUES (1, NULL, TRUE);
SELECT partman.create_parent(p_parent_table := 'public.auth_event', p_control := 'occurred_at',
                             p_interval := '1 month', p_premake := 2);
UPDATE partman.part_config SET retention = '12 months', retention_keep_table = false,
    retention_keep_index = false, infinite_time_partitions = true
WHERE parent_table = 'public.auth_event';
